#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>

int main() {
    int numberOfLines;
    std::cin >> numberOfLines;
    std::cin.ignore(); // ignore the remaining newline after reading numberOfLines
    std::string inputLine;
    std::getline(std::cin, inputLine);

    // Split inputLine by parentheses using a simple approach
    std::vector<std::string> parts;
    std::string temp;
    bool insideParentheses = false;
    for (char ch : inputLine) {
        if (ch == '(') {
            insideParentheses = true;
            temp.clear();
        } else if (ch == ')') {
            insideParentheses = false;
            parts.push_back(temp);
        } else if (insideParentheses) {
            temp += ch;
        } else {
            // For parts outside parentheses, we can ignore or process if needed
            // but the original code only processes parts split by parentheses
            // so we skip outside parts
        }
    }

    int maxLength = 0;
    // For splitting by underscore, use stringstream
    for (const auto& part : parts) {
        std::stringstream ss(part);
        std::string token;
        while (std::getline(ss, token, '_')) {
            if (token.length() > maxLength) {
                maxLength = token.length();
            }
        }
    }

    int totalWords = 0;
    // Count words inside brackets
    size_t startIdx = 0;
    size_t endIdx = 0;
    while ((endIdx = inputLine.find(')', startIdx)) != std::string::npos) {
        size_t openIdx = inputLine.rfind('(', endIdx);
        if (openIdx != std::string::npos && openIdx > startIdx) {
            std::string segment = inputLine.substr(openIdx + 1, endIdx - openIdx - 1);
            std::stringstream ss(segment);
            std::string word;
            while (std::getline(ss, word, '_')) {
                if (!word.empty()) {
                    totalWords++;
                }
            }
        }
        startIdx = endIdx + 1;
    }

    std::cout << maxLength << " " << totalWords << std::endl;

    return 0;
}

